// This cluster's @interface is the SDK's own - iPhoneOS 16.4 declares MTRClusterActions - and it marks
// -initWithDevice:endpointID:queue: NS_DESIGNATED_INITIALIZER, so clang asks the initializer below to call
// a designated initializer of the superclass. MTRCluster.h:40 declares -init NS_UNAVAILABLE, so that call
// cannot be written: `self = [super init]` is `error: 'init' is unavailable`. The initializer therefore does
// what it can - it keeps the three arguments in the ivars below - and this one diagnostic is silenced HERE
// and named, the way MTLRasterizationRate13.m silences its own. The four ways of writing the chain that
// were measured, and the repository's convention, are in coordination/crutches.md.
#pragma clang diagnostic ignored "-Wobjc-designated-initializers"

// A class EXTENSION, not a category: it carries the storage and is invisible at
// runtime, so the port's class is still the only implementation of the name.
@interface MTRClusterActions () {
    id _charon_device;
    NSNumber *_charon_endpoint;
    dispatch_queue_t _charon_queue;
    NSMutableDictionary *_charon_values;
}
@end

// The values the caller has written, by attribute name: this object's own table, made on
// first use. The caller holds the object's lock for the whole of its access, so this takes
// none. It is not keyed by the class: two objects of one class are two tables, as they are
// two sets of state in the framework.
// It takes the table by its address, not the object: naming the class here would not compile
// where the host SDK marks that class unavailable, as it does for some commodity and closure
// clusters.
static NSMutableDictionary *charon_port_values(NSMutableDictionary * __strong *values)
{
    if (!*values) {
        *values = [NSMutableDictionary dictionary];
    }
    return *values;
}

// The error a member that would need a node answers, on a release with no Matter
// hardware: there is no controller to ask and no node to read from. It is the framework's
// own answer to a cached read on a container with no cache and to any request on a
// controller that has been shut down, measured on the host by
// tests/backports/host/matterdifferential/behaviour.m: MTRErrorDomain, MTRErrorCodeInvalidState,
// "Invalid object state.". The domain is written as the string the constant holds: the
// constant is defined by the framework's own build (packages/m/matter), not by this library.
// Built once: every caller gets the same object, and it is made on first use.
static NSError *charon_port_no_node_error(void)
{
    static NSError *error;
    static dispatch_once_t once;
    dispatch_once(&once, ^{
        error = [NSError errorWithDomain:@"MTRErrorDomain" code:MTRErrorCodeInvalidState
                                userInfo:@{NSLocalizedDescriptionKey: @"Invalid object state."}];
    });
    return error;
}

